export function WoulibThemeProvider({children}: {children: React.ReactNode}) { const [dark, setDarkState] = useState(false); useEffect(() => { AsyncStorage.getItem(KEY).then(v => { if (v === 'dark') setDarkState(true); }).catch(() => {}); }, []); const setDark = useCallback((d: boolean) => { setDarkState(d); AsyncStorage.setItem(KEY, d ? 'dark' : 'light').catch(() => {}); }, []); const value = useMemo(() => ({t: dark ? darkTheme : lightTheme, dark, setDark, toggle: () => setDark(!dark)}), [dark, setDark]); return <ThemeCtx.Provider value={value}>{children}</ThemeCtx.Provider>; }
