export type Pt = [number, number]; export interface LatLng {latitude: number; longitude: number}
export const GEO: Record<string, LatLng> = {'Current location': {latitude: 0, longitude: 0}, 'City Center': {latitude: 0.003, longitude: 0.004}, 'Business District': {latitude: -0.002, longitude: 0.006}, 'Airport': {latitude: 0.006, longitude: -0.004}, 'Shopping District': {latitude: -0.004, longitude: -0.003}, 'Downtown': {latitude: 0.002, longitude: -0.006}};
export const haversine = (a: LatLng, b: LatLng) => { const r = Math.PI / 180, dLa = (b.latitude - a.latitude) * r, dLo = (b.longitude - a.longitude) * r; const h = Math.sin(dLa / 2) ** 2 + Math.cos(a.latitude * r) * Math.cos(b.latitude * r) * Math.sin(dLo / 2) ** 2; return 12742 * Math.asin(Math.sqrt(h)); };
export const gridToLL = (trip: {A: Pt; fromLL: LatLng}, p: Pt): LatLng => ({latitude: trip.fromLL.latitude - (p[1] - trip.A[1]) * 0.000026, longitude: trip.fromLL.longitude + (p[0] - trip.A[0]) * 0.00027});
