export const hash = (s: string) => { let h = 7; for (const c of s) h = (h * 31 + c.charCodeAt(0)) >>> 0; return (h % 2147483646) + 1; }; export const rng = (seed: number) => () => (seed = (seed * 16807) % 2147483647) / 2147483647; export const dedupe = (p: Pt[]) => p.filter((a, i) => !i || a[0] !== p[i - 1][0] || a[1] !== p[i - 1][1]); const clamp = (v: number, a: number, b: number) => Math.min(b, Math.max(a, v));
export function smooth(p: Pt[], r = 32): Pt[] { if (p.length < 3) return p.map(a => [a[0], a[1]] as Pt); const o: Pt[] = [[p[0][0], p[0][1]]]; for (let i = 1; i < p.length - 1; i++) { const a = p[i - 1], b = p[i], c = p[i + 1], l1 = Math.hypot(b[0] - a[0], b[1] - a[1]), l2 = Math.hypot(c[0] - b[0], c[1] - b[1]), k = Math.min(r, l1 / 2, l2 / 2); const s: Pt = [b[0] + ((a[0] - b[0]) / l1) * k, b[1] + ((a[1] - b[1]) / l1) * k], e: Pt = [b[0] + ((c[0] - b[0]) / l2) * k, b[1] + ((c[1] - b[1]) / l2) * k]; for (let t = 0; t <= 8; t++) { const u = t / 8, w = 1 - u; o.push([w * w * s[0] + 2 * w * u * b[0] + u * u * e[0], w * w * s[1] + 2 * w * u * b[1] + u * u * e[1]]); } } o.push([p[p.length - 1][0], p[p.length - 1][1]]); return o; }
export function along(path: Pt[], q: number): [number, number, number] { 'worklet'; const n = path.length; let L = 0; for (let i = 1; i < n; i++) L += Math.hypot(path[i][0] - path[i - 1][0], path[i][1] - path[i - 1][1]); let d = Math.min(1, Math.max(0, q)) * L; for (let i = 1; i < n; i++) { const dx = path[i][0] - path[i - 1][0], dy = path[i][1] - path[i - 1][1], l = Math.hypot(dx, dy); if (d <= l || i === n - 1) { const f = l ? Math.min(1, d / l) : 0; return [path[i - 1][0] + dx * f, path[i - 1][1] + dy * f, Math.atan2(dy, dx)]; } d -= l; } return [path[0][0], path[0][1], 0]; }
export const ease = (q: number) => { 'worklet'; return 0.5 * q + 0.5 * q * q * (3 - 2 * q); };
export interface Trip {from: string; dest: string; A: Pt; D: Pt; path: Pt[]; km: string; min: number; fromLL: LatLng; toLL: LatLng}
export function makeTrip(from: string, dest: string): Trip { const R = rng(hash(from + '>' + dest)); const I = () => (1 + Math.floor(R() * 6)) * 100; let A: Pt, D: Pt; do { A = [I(), I()]; D = [I(), I()]; } while (Math.abs(A[0] - D[0]) + Math.abs(A[1] - D[1]) < 300); const path = dedupe(R() < 0.5 ? [A, [A[0], D[1]], D] : [A, [D[0], A[1]], D]); const fromLL = GEO[from.split(',')[0]] ?? GEO['Current location']; let toLL = GEO[dest] ?? GEO['City Center']; if (haversine(fromLL, toLL) < 0.5) toLL = {latitude: toLL.latitude + 0.006, longitude: toLL.longitude + 0.004}; const road = haversine(fromLL, toLL) * 1.35, km = road.toFixed(1); return {from, dest, A, D, path, km, min: Math.max(4, Math.round((road / 18) * 60) + 2), fromLL, toLL}; }
export interface Driver {id: string; name: string; first: string; initial: string; color: string; plate: string; rating: string; trips: string; pos: Pt; eta: number; diff: number; phone: string}
const NAMES = ['Ronald Richards', 'Jane Cooper', 'Marcus Lee', 'Sofia Alvarez', 'Daniel Okafor', 'Priya Nair', 'Jean Pierre', 'Marie Joseph']; const COLORS = ['#5b7fd0', '#e0714f', '#4aa391', '#b36fc4', '#d0a23b', '#d0587f'];
export function makeDrivers(A: Pt): Driver[] { const R = rng((Date.now() % 2147483646) + 1), names = [...NAMES].sort(() => R() - 0.5); const rp = (): Pt => { let p: Pt; do { p = [clamp(A[0] + (Math.floor(R() * 7) - 3) * 100, 100, 700), clamp(A[1] + (Math.floor(R() * 7) - 3) * 100, 100, 700)]; } while (Math.abs(p[0] - A[0]) + Math.abs(p[1] - A[1]) < 200); return p; }; return [0, 1, 2, 3].map(i => ({id: 'd' + i, name: names[i], first: names[i].split(' ')[0], initial: names[i][0], color: COLORS[(Math.floor(R() * 6) + i) % 6], plate: 'WL ' + (1000 + Math.floor(R() * 9000)), rating: (4.6 + Math.floor(R() * 5) / 10).toFixed(1), trips: String(200 + Math.floor(R() * 2800)), phone: '+1202555' + (1000 + Math.floor(R() * 8999)), pos: rp(), eta: 2 + Math.floor(R() * 6), diff: 2 + Math.floor(R() * 7) + [0, 0.3, 0.5][Math.floor(R() * 3)]})); }
export type RideStatus = 'idle' | 'searching' | 'offer' | 'declined' | 'confirmed' | 'onway' | 'arrived'; export type WoulibMode = 'ride' | 'delivery'; export type ProviderStatus = 'offline' | 'online' | 'request' | 'accept' | 'arriving' | 'arrived' | 'trip' | 'complete' | 'earnings';
export interface WantissUserRef { id: string; displayName?: string; email?: string; role?: string; } export interface WoulibRideRecord { id: string; userId: string; mode: WoulibMode; from: string; destination: string; status: string; fare?: number; } export interface WoulibDriverProviderRef { id: string; userId?: string; providerType: 'driver' | 'delivery_provider'; status: ProviderStatus; } export interface WantissWalletTransaction { id: string; userId: string; type: 'ride' | 'delivery' | 'refund' | 'earning'; amount: number; currency: string; referenceId?: string; } export interface WantissNotificationRef { id: string; userId: string; type: string; title: string; body: string; read?: boolean; referenceId?: string; } export interface WoulibRideHistoryEntry { id: string; userId: string; mode: WoulibMode; completedAt?: string; from: string; destination: string; fare?: number; }
export interface Tracking {path: Pt[]; startedAt: number; duration: number} export interface RideState {from: string; dest: string; vehicle: Vehicle; payment: Pay; trip: Trip | null; mode: WoulibMode; status: RideStatus; drivers: Driver[]; shown: Record<string, boolean>; declined: Record<string, boolean>; highlight: string | null; offerIdx: number; found: number; toast: string | null; price: number; accepted: Driver | null; tracking: Tracking | null; eta: number; landmark: string; mapView: 'illustrated' | 'live'; providerStatus: ProviderStatus;}
export interface WoulibRideService { createDrivers(trip: Trip): Driver[]; clear(): void; } export interface WoulibProviderLifecycle { status: ProviderStatus; setStatus(status: ProviderStatus): void; } export function createDemoWoulibRideService(): WoulibRideService { return {createDrivers: trip => makeDrivers(trip.A), clear: () => {}}; }
export interface RideApi extends RideState { setDest(name: string): void; cycleFrom(): void; setVehicle(v: Vehicle): void; setPayment(p: Pay): void; setMode(mode: WoulibMode): void; startSearch(): void; decline(): void; accept(): void; cancel(): void; setLandmark(t: string): void; setMapView(v: 'illustrated' | 'live'): void; setProviderStatus(status: ProviderStatus): void; }
const INIT: RideState = {from: FROMS[0], dest: PLACES[0].n, vehicle: VEHICLES[0], payment: PAYMENTS[0], trip: null, mode: 'ride', status: 'idle', drivers: [], shown: {}, declined: {}, highlight: null, offerIdx: 0, found: 0, toast: null, price: 0, accepted: null, tracking: null, eta: 5, landmark: '', mapView: 'illustrated', providerStatus: 'offline'};
const RideCtx = createContext<RideApi>(null as unknown as RideApi); export const useRide = () => useContext(RideCtx);
export function createProviderLifecycle(status: ProviderStatus = 'offline'): WoulibProviderLifecycle { let current = status; return {get status() { return current; }, setStatus(next) { current = next; }}; }
export function RideProvider({children, service}: {children: React.ReactNode; service?: WoulibRideService}) { const rideService = useMemo(() => service ?? createDemoWoulibRideService(), [service]); const [s, setS] = useState<RideState>(INIT); const sr = useRef(s); sr.current = s; const timers = useRef<ReturnType<typeof setTimeout>[]>([]); const tick = useRef<ReturnType<typeof setInterval> | null>(null); const later = (ms: number, f: () => void) => { timers.current.push(setTimeout(f, ms)); }; const clear = () => { timers.current.forEach(clearTimeout); timers.current = []; if (tick.current) { clearInterval(tick.current); tick.current = null; } }; useEffect(() => () => { clear(); rideService.clear(); }, [rideService]); const patch = (p: Partial<RideState>) => setS(x => ({...x, ...p})); const offer = (i: number) => { const d = sr.current.drivers[i]; if (!d) return; setS(x => ({...x, status: 'offer', offerIdx: i, highlight: d.id, shown: {...x.shown, [d.id]: true}, declined: {...x.declined, [d.id]: false}, price: +(x.vehicle.price + d.diff).toFixed(2)})); }; const api: RideApi = {...s, setDest: name => setS(x => ({...x, dest: name, trip: makeTrip(x.from, name)})), cycleFrom: () => setS(x => { const from = FROMS[(FROMS.indexOf(x.from) + 1) % FROMS.length]; return {...x, from, trip: x.trip ? makeTrip(from, x.dest) : null}; }), setVehicle: v => patch({vehicle: v}), setPayment: p => patch({payment: p}), setMode: mode => patch({mode}), setLandmark: l => patch({landmark: l}), setMapView: v => patch({mapView: v}), setProviderStatus: providerStatus => patch({providerStatus}), startSearch: () => { clear(); const trip = sr.current.trip; if (!trip) return; setS(x => ({...x, drivers: rideService.createDrivers(trip), status: 'searching', shown: {}, declined: {}, highlight: null, offerIdx: 0, found: 0, toast: null, accepted: null, tracking: null, eta: 5})); later(1500, () => setS(x => ({...x, found: 2, shown: {...x.shown, [x.drivers[2].id]: true, [x.drivers[3].id]: true}}))); later(2800, () => setS(x => ({...x, found: 3, shown: {...x.shown, [x.drivers[0].id]: true}}))); later(3600 + Math.random() * 1800, () => offer(0)); }, decline: () => { const x0 = sr.current, d = x0.drivers[x0.offerIdx], next = (x0.offerIdx + 1) % 2; setS(x => ({...x, status: 'declined', highlight: null, declined: {...x.declined, [d.id]: true}, toast: `You declined ${d.first}'s offer`})); later(3000, () => patch({toast: null})); if (next === 1) later(1800, () => setS(x => ({...x, found: x.found + 1, shown: {...x.shown, [x.drivers[1].id]: true}}))); later(3800, () => offer(next)); }, accept: () => { const x0 = sr.current, d = x0.drivers[x0.offerIdx], trip = x0.trip!; clear(); patch({status: 'confirmed', highlight: null, accepted: d}); later(2800, () => { const mid: Pt = Math.random() < 0.5 ? [d.pos[0], trip.A[1]] : [trip.A[0], d.pos[1]], path = smooth(dedupe([d.pos, mid, trip.A])); const duration = 17500, startedAt = Date.now() + 1200; patch({status: 'onway', tracking: {path, startedAt, duration}, eta: 5}); tick.current = setInterval(() => { const q = (Date.now() - startedAt) / duration; if (q >= 1) { clearInterval(tick.current!); tick.current = null; patch({status: 'arrived', eta: 0}); return; } const eta = Math.max(1, Math.ceil(5 * (1 - Math.max(0, q)))); if (eta !== sr.current.eta) patch({eta}); }, 250); }); }, cancel: () => { clear(); setS(x => ({...x, status: 'idle', tracking: null, shown: {}, drivers: [], highlight: null, toast: null, accepted: null})); }}; return <RideCtx.Provider value={useMemo(() => api, [s])}>{children}</RideCtx.Provider>; }

const NB = 8, SW = 2080, SH = 1340, OX = 1040, OY = 320; const P = (x: number, y: number, z = 0): [number, number] => { 'worklet'; return [(x - y) * 0.866, (x + y) * 0.5 - z]; }; const pts = (a: [number, number][]) => a.map(p => `${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(' '); const pd = (a: [number, number][]) => 'M' + a.map(p => `${p[0].toFixed(1)} ${p[1].toFixed(1)}`).join('L') + 'Z';
type Shape = {k: 'p'; pts: string; f: string; o?: number; s?: string; w?: number} | {k: 'd'; d: string; f: string; o?: number} | {k: 'c'; x: number; y: number; r: number; f: string} | {k: 'e'; x: number; y: number; rx: number; ry: number; f: string; s?: string; w?: number} | {k: 'l'; pts: string; s: string; w: number; dash: string; o: number};
const poly = (a: [number, number][], f: string, o?: number, s?: string, w?: number): Shape => ({k: 'p', pts: pts(a), f, o, s, w}); const hx = (h: string) => [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16)); const mix = (a: string, b: string, k: number) => { const x = hx(a), y = hx(b); return '#' + x.map((v, i) => Math.round(v + (y[i] - v) * k).toString(16).padStart(2, '0')).join(''); }; type Dk = (c: string) => string;
function box(x0: number, y0: number, x1: number, y1: number, z0: number, z1: number, c: string[], win: boolean, d: Dk, sx = 0, sy = 0): Shape[] { const o: Shape[] = [poly([P(x0, y1, z0), P(x1, y1, z0), P(x1, y1, z1), P(x0, y1, z1)], d(c[1])), poly([P(x1, y0, z0), P(x1, y1, z0), P(x1, y1, z1), P(x1, y0, z1)], d(c[2])), poly([P(x0, y0, z1), P(x1, y0, z1), P(x1, y1, z1), P(x0, y1, z1)], d(c[0]))]; if (win) { const dx = x1 - x0, dy = y1 - y0, n1 = Math.max(2, Math.floor(dx / 17)), n2 = Math.max(2, Math.floor(dy / 17)); let a1 = '', a2 = ''; for (let a = z0 + 13; a + 9 < z1 - 4; a += 17) { for (let q = 0; q < n1; q++) { const u = 0.1 + (0.8 * q) / n1, v = u + (0.8 / n1) * 0.6; a1 += pd([P(x0 + dx * u, y1, a), P(x0 + dx * v, y1, a), P(x0 + dx * v, y1, a + 9), P(x0 + dx * u, y1, a + 9)]); } for (let q = 0; q < n2; q++) { const u = 0.1 + (0.8 * q) / n2, v = u + (0.8 / n2) * 0.6; a2 += pd([P(x1, y0 + dy * u, a), P(x1, y0 + dy * v, a), P(x1, y0 + dy * v, a + 9), P(x1, y0 + dy * u, a + 9)]); } } o.push({k: 'd', d: a1, f: d('#7fa3cf'), o: 0.9}, {k: 'd', d: a2, f: d('#5a7fae'), o: 0.9}, poly([P(x0, y1, z0), P(x1, y1, z0), P(x1, y1, z0 + 9), P(x0, y1, z0 + 9)], d('#4b5266'), 0.45), poly([P(x1, y0, z0), P(x1, y1, z0), P(x1, y1, z0 + 9), P(x1, y0, z0 + 9)], d('#3a4052'), 0.45)); } return o; }
const PAL = [['#eef0f7', '#dfe3f0', '#c4cae0'], ['#f5e5c6', '#ecd6ad', '#d9bf90'], ['#f2cdb0', '#e8b896', '#d39c78'], ['#e6efdf', '#d3e2c9', '#b9cfae']];
