function Txt({children, size = 15, w = '400', c = 'ink', style}: {children: React.ReactNode; size?: number; w?: any; c?: string; style?: StyleProp<TextStyle>}) { const {t} = useWoulibTheme(); const color = c === 'ink' ? t.ink : c === 'muted' ? t.muted : c === 'red' ? t.red : c; return <Text style={[{fontSize: size, fontWeight: w, color}, style]}>{children}</Text>; }
