function Btn({label, icon, variant = 'primary', height = 54, onPress, style}: {label: string; icon?: any; variant?: 'primary' | 'outline' | 'soft' | 'danger'; height?: number; onPress?: () => void; style?: StyleProp<ViewStyle>}) { const {t} = useWoulibTheme(); const bg = variant === 'primary' ? YELLOW : variant === 'soft' ? t.soft : variant === 'danger' ? t.redSoft : 'transparent'; const fg = variant === 'danger' ? t.red : '#111'; return <Pressable onPress={onPress} style={[{height, borderRadius: 12, backgroundColor: bg, borderWidth: variant === 'outline' ? 1 : 0, borderColor: t.line, alignItems: 'center', justifyContent: 'center', flexDirection: 'row', gap: 8}, style]}>{icon && <Ionicons name={icon} size={18} color={fg} />}<Txt w="700" c={variant === 'danger' ? t.red : '#111'}>{label}</Txt></Pressable>; }
function ThemeToggle() { const {dark, toggle, t} = useWoulibTheme(); return <Pressable onPress={toggle} style={{width: 46, height: 42, borderRadius: 14, backgroundColor: t.soft, alignItems: 'center', justifyContent: 'center'}}><Ionicons name={dark ? 'sunny' : 'moon'} size={19} color={t.ink} /></Pressable>; } function Logo() { return <Txt size={26} w="800" c={YELLOW}>Woulib</Txt>; } function Stripes() { return <View pointerEvents="none" style={{position: 'absolute', left: 0, right: 0, top: 0, height: 120, opacity: 0.35}}><Svg width="100%" height="100%"><Defs><LinearGradient id="stripe" x1="0" y1="0" x2="1" y2="1"><Stop offset="0" stopColor={YELLOW} stopOpacity="0.35" /><Stop offset="1" stopColor={YELLOW} stopOpacity="0" /></LinearGradient></Defs><Rect width="100%" height="100%" fill="url(#stripe)" /></Svg></View>; }
function Hero() { const {t} = useWoulibTheme(); return <View style={{height: 134, borderRadius: 20, overflow: 'hidden', backgroundColor: t.soft, marginBottom: 14}}><Svg width="100%" height="100%"><Defs><LinearGradient id="fd" x1="0" y1="0" x2="1" y2="1"><Stop offset="0" stopColor="#2a313d" /><Stop offset="1" stopColor="#0f1117" /></LinearGradient></Defs><Rect width="270" height="134" fill="url(#fd)" /><Path d="M120 104L190 74 240 92 295 64 380 94V134H120z" fill="#2a313d" /><Path d="M215 134L322 92 346 92 372 134z" fill="#4a4a50" /><Path d="M322 76c-10-13-16-20-16-28a16 16 0 0132 0c0 8-6 15-16 28z" fill={YELLOW} /><Circle cx="322" cy="48" r="6" fill="#14161d" /><Rect width="270" height="134" fill="url(#fd)" /></Svg><View style={{position: 'absolute', left: 24, top: 28}}><Txt size={19} w="600" c="#fff" style={{lineHeight: 25}}>You're already going{'
'}there. Why not</Txt><Txt size={19} w="700" c={YELLOW} style={{lineHeight: 25}}>share the ride?</Txt></View></View>; }
function Row({icon, label, value, onPress, last, chevron = 'chevron-forward', dim}: {icon: React.ReactNode; label: string; value: string; onPress: () => void; last?: boolean; chevron?: string; dim?: boolean}) { const {t} = useWoulibTheme(); return <Pressable onPress={onPress} style={{flexDirection: 'row', alignItems: 'center', gap: 14, paddingVertical: 14, borderBottomWidth: last ? 0 : 1, borderBottomColor: t.line, flex: 1}}><View style={{width: 26, alignItems: 'center'}}>{icon}</View><View style={{flex: 1}}><Txt w="600">{label}</Txt><Txt size={13.5} c={dim ? 'muted' : 'ink'}>{value}</Txt></View><Ionicons name={chevron as any} size={18} color={t.muted} /></Pressable>; }
function RingIcon() { return <View style={{width: 16, height: 16, borderRadius: 8, borderWidth: 3, borderColor: YELLOW}} />; } function PinIcon() { return <Ionicons name="location" size={19} color={YELLOW} />; } function Avatar({initial, color = '#5b7fd0', size = 40}: {initial: string; color?: string; size?: number}) { return <View style={{width: size, height: size, borderRadius: size / 2, backgroundColor: color, alignItems: 'center', justifyContent: 'center'}}><Txt c="#fff" w="800" size={size * 0.38}>{initial}</Txt></View>; } function CarThumb({width = 84, color = '#c9ccd6'}: {width?: number; color?: string}) { return <View style={{width, height: width * 0.55, borderRadius: width * 0.2, backgroundColor: color, alignItems: 'center', justifyContent: 'center'}}><Ionicons name="car-sport" size={width * 0.55} color="#1d1d22" /></View>; } function PayBadge({badge, color}: {badge: string; color: string}) { return <View style={{backgroundColor: color, borderRadius: 6, paddingHorizontal: 6, paddingVertical: 3}}><Text style={{fontSize: 9, color: '#fff', fontWeight: '800'}}>{badge}</Text></View>; }
function TopBar({children, onBack, right}: {children?: React.ReactNode; onBack?: () => void; right?: React.ReactNode}) { const {t} = useWoulibTheme(); return <View style={{position: 'absolute', left: 12, right: 12, top: Platform.OS === 'ios' ? 54 : 28, height: 52, flexDirection: 'row', alignItems: 'center', gap: 10}}>{onBack && <Pressable onPress={onBack} style={{width: 46, height: 46, borderRadius: 16, backgroundColor: t.card, alignItems: 'center', justifyContent: 'center'}}><Ionicons name="arrow-back" size={21} color={t.ink} /></Pressable>}<View style={{flex: 1, height: 46, borderRadius: 16, backgroundColor: t.card, flexDirection: 'row', alignItems: 'center', paddingHorizontal: 14, gap: 9}}>{children}</View>{right}</View>; }
function Sheet({visible, children, maxHeight = '48%', spring = false, delayIn = 0}: {visible: boolean; children: React.ReactNode; maxHeight?: string; spring?: boolean; delayIn?: number}) { const {t} = useWoulibTheme(); if (!visible) return null; return <Animated.View entering={(spring ? ZoomIn : FadeInDown).delay(delayIn).duration(360)} style={{position: 'absolute', left: 10, right: 10, bottom: 10, maxHeight: maxHeight as any, borderRadius: 24, padding: 16, backgroundColor: t.card}}>{children}</Animated.View>; }
function Stepper({step}: {step: number}) { return <View style={{flexDirection: 'row', gap: 5}}>{[0,1,2,3].map(i => <View key={i} style={{height: 6, width: 26, borderRadius: 99, backgroundColor: i <= step ? YELLOW : '#ddd'}} />)}</View>; } function GreenLine({run}: {run: boolean}) { return <View style={{height: 4, backgroundColor: run ? '#1FAE68' : '#ddd', borderRadius: 99, marginTop: 14}} />; }
export interface WoulibHomeProps {onFindRide: () => void; onOfferRide?: () => void; onProfile?: () => void; onTab?: (tab: 'home' | 'search' | 'offer' | 'profile') => void;}
export function WoulibHomeScreen({onFindRide, onOfferRide = () => {}, onProfile, onTab}: WoulibHomeProps) { const {t} = useWoulibTheme(); const ride = useRide(); const [di, setDi] = useState(0), [ti, setTi] = useState(0), [pi, setPi] = useState(0); const dates = ['Today', 'Tomorrow', 'In 2 days'], times = ['Anytime', '8:00 AM', '5:00 PM'], pax = ['1 passenger', '2 passengers', '3 passengers']; const chosen = !!ride.trip; const icon = (n: any) => <Ionicons name={n} size={22} color={t.ink} />; return <View style={{flex: 1, backgroundColor: t.bg}}><Stripes /><ScrollView contentContainerStyle={{paddingTop: 28, paddingHorizontal: 16, paddingBottom: 110}} showsVerticalScrollIndicator={false}><View style={{flexDirection: 'row', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 18}}><View><Logo /><Txt size={13} style={{marginTop: 4}}>Share rides. Go further.</Txt></View><View style={{flexDirection: 'row', gap: 10, marginTop: 6}}><ThemeToggle /><Pressable onPress={onProfile} style={{width: 42, height: 42, borderRadius: 21, borderWidth: 2.5, borderColor: YELLOW, alignItems: 'center', justifyContent: 'center'}}><Ionicons name="person" size={19} color={t.ink} /></Pressable></View></View><Hero /><View style={{flexDirection: 'row', backgroundColor: t.soft, borderRadius: 14, padding: 4, marginBottom: 14}}><Pressable onPress={() => ride.setMode('ride')} style={{flex: 1, paddingVertical: 10, borderRadius: 11, backgroundColor: ride.mode === 'ride' ? t.card : 'transparent', alignItems: 'center'}}><Txt size={13.5} w={ride.mode === 'ride' ? '700' : '500'}>Ride</Txt><Txt size={11} c="muted">Passenger transportation</Txt></Pressable><Pressable onPress={() => ride.setMode('delivery')} style={{flex: 1, paddingVertical: 10, borderRadius: 11, backgroundColor: ride.mode === 'delivery' ? t.card : 'transparent', alignItems: 'center'}}><Txt size={13.5} w={ride.mode === 'delivery' ? '700' : '500'}>Delivery</Txt><Txt size={11} c="muted">Goods transportation</Txt></Pressable></View><View style={{flexDirection: 'row', gap: 10, marginBottom: 14}}><Btn label={ride.mode === 'ride' ? 'Find a Ride' : 'Find Delivery'} icon={ride.mode === 'ride' ? 'car' : 'cube'} height={58} onPress={onFindRide} style={{flex: 1}} /><Btn label={ride.mode === 'ride' ? 'Offer a Ride' : 'Offer Delivery'} icon="add" variant="outline" height={58} onPress={onOfferRide} style={{flex: 1}} /></View><Card style={{paddingHorizontal: 16, paddingBottom: 14, marginBottom: 22}}><Row icon={<RingIcon />} label="From" value={chosen ? ride.from.split(',')[0] : 'Where are you leaving from?'} dim={!chosen} onPress={onFindRide} /><Row icon={<PinIcon />} label="To" value={chosen ? ride.dest : 'Where are you going?'} dim={!chosen} onPress={onFindRide} /><View style={{flexDirection: 'row', borderBottomWidth: 1, borderBottomColor: t.line}}><Row icon={icon('calendar-outline')} label="Date" value={dates[di]} chevron="chevron-down" last onPress={() => setDi((di + 1) % 3)} /><View style={{width: 1, backgroundColor: t.line, marginVertical: 10}} /><View style={{flex: 1, paddingLeft: 14}}><Row icon={icon('time-outline')} label="Time" value={times[ti]} chevron="chevron-down" last onPress={() => setTi((ti + 1) % 3)} /></View></View><Row icon={icon('person')} label="Passengers" value={pax[pi]} last onPress={() => setPi((pi + 1) % 3)} /><Btn label="Find Rides" icon="search" height={54} onPress={onFindRide} /></Card><View style={{flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12}}><Txt size={20} w="700">{ride.mode === 'ride' ? 'Nearby Rides' : 'Nearby Deliveries'}</Txt><Txt size={13} c={t.dark ? YELLOW : 'muted'}>See All ›</Txt></View><Card style={{padding: 12, marginBottom: 16}}><View style={{flexDirection: 'row', gap: 14}}><View style={{width: 98, height: 86, borderRadius: 12, backgroundColor: '#3b4452', alignItems: 'center', justifyContent: 'center'}}><CarThumb width={84} color="#11141a" /></View><View style={{flex: 1}}><Txt size={16} w="600">City Center → Business District</Txt><Txt size={13} c="muted" style={{marginVertical: 3}}>Today · 5:00 PM</Txt><View style={{flexDirection: 'row', gap: 14}}><Txt size={13} c="muted">2 seats left</Txt><Txt size={13} c="muted">$150</Txt></View></View></View><View style={{flexDirection: 'row', alignItems: 'center', gap: 10, marginTop: 10}}><Avatar initial="J" size={34} /><View style={{flex: 1}}><Txt size={13}>Jean Pierre D.</Txt><Txt size={11.5} c="muted">★ 4.8 (124 rides)</Txt></View><Pressable onPress={onFindRide} style={{backgroundColor: YELLOW, borderRadius: 99, paddingVertical: 10, paddingHorizontal: 18}}><Txt w="700" size={13} c="#111111">Join Ride →</Txt></Pressable></View></Card><View style={{flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12}}><Txt size={20} w="700">{ride.mode === 'ride' ? 'Your Upcoming Rides' : 'Your Upcoming Deliveries'}</Txt><Txt size={13} c={t.dark ? YELLOW : 'muted'}>See All ›</Txt></View><Card style={{padding: 14}}><Txt size={16} w="600">Business District → City Center</Txt><Txt size={13} c="muted" style={{marginTop: 3}}>Tomorrow · 8:00 AM · 1 passenger · $140</Txt></Card></ScrollView><View style={{position: 'absolute', left: 0, right: 0, bottom: 0, flexDirection: 'row', justifyContent: 'space-around', backgroundColor: t.card, borderTopWidth: 1, borderTopColor: t.line, paddingTop: 10, paddingBottom: 26}}>{([['home', 'home', 'Home'], ['search', 'search', 'Search'], ['offer', 'add-circle-outline', 'Offer'], ['profile', 'person-outline', 'Profile']] as const).map(([k, ic, lb]) => <Pressable key={k} onPress={() => onTab?.(k)} style={{alignItems: 'center', gap: 2}}><Ionicons name={ic as any} size={24} color={k === 'home' ? YELLOW : t.muted} /><Txt size={11} c={k === 'home' ? YELLOW : 'muted'}>{lb}</Txt></Pressable>)}</View></View>; }
export function WoulibRouteScreen({onBack, onContinue}: {onBack: () => void; onContinue: () => void}) { const {t, dark} = useWoulibTheme(); const ride = useRide(); const [picked, setPicked] = useState(false); const trip = picked ? ride.trip : null; const focus = trip ? {x: (trip.A[0] + trip.D[0]) / 2, y: (trip.A[1] + trip.D[1]) / 2, s: 0.95} : {x: 400, y: 400, s: 0.75}; return <View style={{flex: 1, backgroundColor: t.bg}}><WoulibMapView dark={dark} trip={trip} focus={focus} showRoute={picked} pins={{pickup: picked, dest: picked}} /><TopBar onBack={() => (picked ? setPicked(false) : onBack())}><Stepper step={0} /></TopBar><Sheet visible={!picked} maxHeight="68%"><Txt size={22} w="700">{ride.mode === 'ride' ? 'Where to?' : 'Where should we deliver?'}</Txt><Txt size={12} c="muted" style={{marginTop: 2}}>{ride.mode === 'ride' ? "Pick a destination and we'll find rides on the way" : "Pick a destination and we'll find a delivery provider"}</Txt><Card style={{paddingHorizontal: 14, marginTop: 14}}><View style={{flexDirection: 'row', alignItems: 'center', gap: 14, paddingVertical: 12, borderBottomWidth: 1, borderBottomColor: t.line}}><RingIcon /><View style={{flex: 1}}><Txt w="600">From</Txt><Txt size={13.5} c="muted">{ride.from}</Txt></View><View style={{backgroundColor: t.soft, borderRadius: 99, paddingHorizontal: 10, paddingVertical: 4}}><Txt size={11.5}>Current</Txt></View></View><View style={{flexDirection: 'row', alignItems: 'center', gap: 14, paddingVertical: 12}}><PinIcon /><View style={{flex: 1}}><Txt w="600">To</Txt><Txt size={13.5} c="muted">Search a place or address</Txt></View><Ionicons name="search" size={18} color={t.muted} /></View></Card><ScrollView showsVerticalScrollIndicator={false} style={{marginTop: 4}}>{PLACES.map((p, i) => <View key={p.n}>{(i === 0 || i === 2) && <Txt size={11.5} w="600" c="muted" style={{marginTop: 16, marginBottom: 6, letterSpacing: 0.8}}>{i === 0 ? 'RECENT' : 'SUGGESTED'}</Txt>}<Pressable onPress={() => { ride.setDest(p.n); setPicked(true); }} style={{flexDirection: 'row', alignItems: 'center', gap: 12, paddingVertical: 11, borderBottomWidth: 1, borderBottomColor: t.line}}><View style={{width: 38, height: 38, borderRadius: 19, backgroundColor: t.soft, alignItems: 'center', justifyContent: 'center'}}><Ionicons name={i < 2 ? 'time-outline' : 'location-outline'} size={18} color={t.muted} /></View><View style={{flex: 1}}><Txt w="600">{p.n}</Txt><Txt size={12} c="muted">{p.a}</Txt></View><Ionicons name="chevron-forward" size={18} color={t.muted} /></Pressable></View>)}</ScrollView></Sheet><Sheet visible={picked}><Card style={{paddingHorizontal: 14, marginBottom: 12}}><Pressable onPress={ride.cycleFrom} style={{flexDirection: 'row', alignItems: 'center', gap: 14, paddingVertical: 12, borderBottomWidth: 1, borderBottomColor: t.line}}><RingIcon /><View style={{flex: 1}}><Txt w="600">Pickup · tap to change</Txt><Txt size={13.5} c="muted">{ride.from}</Txt></View><Ionicons name="swap-vertical" size={18} color={t.muted} /></Pressable><View style={{flexDirection: 'row', alignItems: 'center', gap: 14, paddingVertical: 12}}><PinIcon /><View style={{flex: 1}}><Txt w="600">Destination</Txt><Txt size={13.5} c="muted">{ride.dest}</Txt></View></View></Card><View style={{backgroundColor: t.soft, borderRadius: 14, paddingHorizontal: 12, marginBottom: 12, flexDirection: 'row', alignItems: 'center', gap: 8}}><Ionicons name="flag-outline" size={18} color={t.muted} /><TextInput value={ride.landmark} onChangeText={ride.setLandmark} placeholder="Pickup landmark (e.g. in front of the pharmacy)" placeholderTextColor={t.muted} style={{flex: 1, paddingVertical: 12, color: t.ink, fontSize: 13}} /></View><View style={{flexDirection: 'row', gap: 8, marginBottom: 14}}>{[['Distance', `${ride.trip?.km ?? '–'} km`], ['Drive time', `${ride.trip?.min ?? '–'} min`], [ride.mode === 'ride' ? 'Ride' : 'Delivery', ride.mode === 'ride' ? 'Shared' : 'Package']].map(([l, v]) => <View key={l} style={{flex: 1, backgroundColor: t.soft, borderRadius: 14, padding: 10}}><Txt size={11.5} c="muted">{l}</Txt><Txt size={15} w="700">{v}</Txt></View>)}</View><Btn label="Continue to payment →" onPress={onContinue} /></Sheet></View>; }
export function WoulibPaymentScreen({onBack, onContinue}: {onBack: () => void; onContinue: () => void}) { const {t} = useWoulibTheme(); const ride = useRide(); return <View style={{flex: 1, backgroundColor: t.bg}}><TopBar onBack={onBack}><Stepper step={1} /></TopBar><ScrollView contentContainerStyle={{padding: 16, paddingTop: Platform.OS === 'ios' ? 120 : 94, paddingBottom: 30}}><Txt size={25} w="800">Payment</Txt><Txt size={12} c="muted" style={{marginTop: 3}}>{ride.mode === 'ride' ? 'Choose how you want to pay for the ride.' : 'Choose how you want to pay for the delivery.'}</Txt><View style={{marginTop: 18}}>{PAYMENTS.map(p => { const sel = ride.payment.id === p.id; return <Pressable key={p.id} onPress={() => ride.setPayment(p)} style={{flexDirection: 'row', alignItems: 'center', gap: 12, backgroundColor: t.card, borderRadius: 16, borderWidth: 1.5, borderColor: sel ? YELLOW : t.line, padding: 14, marginBottom: 8}}><PayBadge badge={p.badge} color={p.color} /><View style={{flex: 1}}><Txt w="700">{p.name}</Txt><Txt size={12} c="muted">{p.sub}</Txt></View><Ionicons name={sel ? 'checkmark-circle' : 'ellipse-outline'} size={23} color={sel ? YELLOW : t.muted} /></Pressable>; })}</View><Btn label="Continue →" onPress={onContinue} style={{marginTop: 8}} /></ScrollView></View>; }
export function WoulibCarScreen({onBack, onChangePayment, onFindDriver}: {onBack: () => void; onChangePayment?: () => void; onFindDriver: () => void}) { const {t} = useWoulibTheme(); const ride = useRide(); return <View style={{flex: 1, backgroundColor: t.bg}}><TopBar onBack={onBack}><Stepper step={2} /></TopBar><ScrollView contentContainerStyle={{padding: 16, paddingTop: Platform.OS === 'ios' ? 120 : 94, paddingBottom: 30}}><Txt size={25} w="800">{ride.mode === 'ride' ? 'Choose a ride' : 'Choose transport'}</Txt><Txt size={12} c="muted" style={{marginTop: 3}}>{ride.mode === 'ride' ? 'Select the vehicle that fits your trip.' : 'Select the vehicle that fits the goods you are moving.'}</Txt><View style={{marginTop: 18}}>{VEHICLES.map(v => { const sel = ride.vehicle.id === v.id; return <Pressable key={v.id} onPress={() => ride.setVehicle(v)} style={{flexDirection: 'row', alignItems: 'center', gap: 12, backgroundColor: t.card, borderRadius: 18, borderWidth: 1.5, borderColor: sel ? YELLOW : t.line, padding: 10, marginBottom: 10}}><CarThumb width={74} color={v.color} /><View style={{flex: 1}}><Txt w="700">{v.name}</Txt><Txt size={12} c="muted">{v.seats} seats · {etaRange(v.eta)} min</Txt></View><Txt size={17} w="800">${v.price.toFixed(2)}</Txt></Pressable>; })}</View><Pressable onPress={onChangePayment} style={{flexDirection: 'row', alignItems: 'center', gap: 10, paddingVertical: 12}}><PayBadge badge={ride.payment.badge} color={ride.payment.color} /><View style={{flex: 1}}><Txt w="600">{ride.payment.name}</Txt><Txt size={12} c="muted">{ride.payment.sub}</Txt></View><Ionicons name="chevron-forward" size={18} color={t.muted} /></Pressable><Btn label={ride.mode === 'ride' ? 'Find my driver →' : 'Find delivery provider →'} onPress={() => { ride.startSearch(); onFindDriver(); }} style={{marginTop: 8}} /></ScrollView></View>; }
export function WoulibRideScreen({onExit}: {onExit: () => void}) { const {t, dark} = useWoulibTheme(); const ride = useRide(); const {trip, vehicle, payment, status, accepted: acc} = ride; const focus = trip ? {x: (trip.A[0] + trip.D[0]) / 2, y: (trip.A[1] + trip.D[1]) / 2, s: 0.95} : {x: 400, y: 400, s: 0.75}; const mapDrivers: MapDriver[] = ride.drivers.map(d => ({id: d.id, initial: d.initial, color: d.color, eta: d.eta, pos: d.pos, vis: !!ride.shown[d.id] && status !== 'confirmed', hl: ride.highlight === d.id, dim: !!ride.declined[d.id]})); const live = status === 'onway' || status === 'arrived'; const offerDrv = ride.drivers[ride.offerIdx]; const eta = ride.eta; const pill = status === 'searching' ? (ride.found ? `${ride.found} drivers found` : 'Searching nearby…') : status === 'offer' ? `Offer from ${offerDrv?.first}` : status === 'declined' ? 'Looking for another driver…' : status === 'confirmed' ? (ride.mode === 'ride' ? 'Ride confirmed' : 'Delivery confirmed') : status === 'onway' ? 'Driver on the way' : status === 'arrived' ? 'Driver has arrived' : ''; const pillRight = status === 'onway' ? `${etaRange(eta)} min` : status === 'arrived' ? 'Now' : ''; const searchSheet = status === 'searching' || status === 'declined'; const first = acc?.first ?? ''; const driverRow = (d = acc) => d && <View style={{flexDirection: 'row', alignItems: 'center', gap: 11}}><Avatar initial={d.initial} color={d.color} size={46} /><View style={{flex: 1}}><View style={{flexDirection: 'row', alignItems: 'center', gap: 5}}><Txt size={15} w="700">{d.name}</Txt><Ionicons name="checkmark-circle" size={15} color="#2f7cf6" /></View><Txt size={11.5} c="muted">★ {d.rating} · {d.trips} trips</Txt></View><CarThumb color={vehicle.color} width={70} /></View>; return <View style={{flex: 1, backgroundColor: t.bg}}><WoulibMapView dark={dark} trip={trip} focus={focus} pins={{pickup: true}} drivers={mapDrivers} searching={status === 'searching' || status === 'offer' || status === 'declined'} tracking={live ? ride.tracking : null} /><TopBar onBack={status === 'searching' || status === 'declined' ? () => { ride.cancel(); onExit(); } : undefined}><View style={{width: 9, height: 9, borderRadius: 5, backgroundColor: status === 'onway' ? t.green : YELLOW}} /><Animated.View key={pill} entering={FadeIn.duration(180)} style={{flex: 1}}><Txt w="600" numberOfLines={1}>{pill}</Txt></Animated.View>{!!pillRight && <Animated.View key={pillRight} entering={FadeIn.duration(180)}><Txt c="muted">{pillRight}</Txt></Animated.View>}</TopBar><Sheet visible={searchSheet} delayIn={status === 'declined' ? 380 : 500}><Txt size={22} w="700">{ride.mode === 'ride' ? 'Finding your driver' : 'Finding your delivery provider'}</Txt><Txt size={12} c="muted" style={{marginTop: 2}}>{ride.mode === 'ride' ? `Asking ${vehicle.name} drivers near you` : 'Asking delivery providers near you'}</Txt><View style={{flexDirection: 'row', alignItems: 'center', gap: 12, marginTop: 14}}><CarThumb color={vehicle.color} width={70} /><View style={{flex: 1}}><Txt w="700">{vehicle.short}</Txt><Txt size={11.5} c="muted">{payment.name}</Txt></View><Txt size={17} w="700">${vehicle.price.toFixed(2)}</Txt></View><View style={{flexDirection: 'row', alignItems: 'center', gap: 10, backgroundColor: t.soft, padding: 12, borderRadius: 14, marginTop: 14}}><Ionicons name="radio-outline" size={18} color={YELLOW} /><Txt>{ride.found} drivers nearby, waiting for an answer</Txt></View>{ride.toast && <Animated.View entering={FadeInDown.duration(250)} style={{marginTop: 10, backgroundColor: t.redSoft, padding: 10, borderRadius: 12}}><Txt size={12.5} c={t.red}>{ride.toast}</Txt></Animated.View>}<Btn label="Cancel search" variant="danger" onPress={() => { ride.cancel(); onExit(); }} style={{marginTop: 12}} /></Sheet><Sheet visible={status === 'offer'} spring delayIn={340}>{offerDrv && <View key={offerDrv.id}><Animated.View entering={FadeInDown.delay(200).duration(300)}><Txt size={12} w="700" c={YELLOW} style={{marginBottom: 8}}>New offer</Txt></Animated.View><Animated.View entering={FadeInDown.delay(260).duration(300)}>{driverRow(offerDrv)}</Animated.View><Animated.View entering={FadeInDown.delay(320).duration(300)} style={{flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginTop: 12}}><Txt size={15} w="700">{vehicle.name}</Txt><View style={{backgroundColor: t.soft, borderRadius: 10, paddingHorizontal: 11, paddingVertical: 6}}><Txt size={12}>{offerDrv.plate}</Txt></View></Animated.View><Animated.View entering={FadeInDown.delay(380).duration(300)} style={{flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginTop: 12}}><View style={{backgroundColor: t.soft, borderRadius: 10, paddingHorizontal: 11, paddingVertical: 6}}><Txt size={12}>{etaRange(offerDrv.eta)} min away</Txt></View><View style={{alignItems: 'flex-end'}}><View style={{flexDirection: 'row', gap: 8, alignItems: 'center'}}><Txt size={13} c="muted" style={{textDecorationLine: 'line-through'}}>${vehicle.price.toFixed(2)}</Txt><View style={{backgroundColor: t.redSoft, borderRadius: 99, paddingHorizontal: 8, paddingVertical: 2}}><Txt size={11.5} c={t.red}>+${offerDrv.diff.toFixed(2)}</Txt></View></View><Txt size={24} w="800">${ride.price.toFixed(2)}</Txt></View></Animated.View><Animated.View entering={FadeInDown.delay(460).duration(300)} style={{flexDirection: 'row', gap: 10, marginTop: 14}}><Btn label="Decline" variant="danger" onPress={ride.decline} style={{flex: 1}} /><Btn label={`Accept $${ride.price.toFixed(2)}`} onPress={ride.accept} style={{flex: 1.5}} /></Animated.View></View>}</Sheet><Sheet visible={status === 'confirmed'}><View style={{alignItems: 'center'}}><Animated.View entering={ZoomIn.delay(150).duration(320)} style={{width: 68, height: 68, borderRadius: 34, backgroundColor: t.green, alignItems: 'center', justifyContent: 'center', marginBottom: 10}}><Ionicons name="checkmark" size={40} color="#fff" /></Animated.View><Txt size={22} w="700">{ride.mode === 'ride' ? 'Ride confirmed' : 'Delivery confirmed'}</Txt><Txt size={12} c="muted" style={{marginTop: 2}}>{first} is on the way in the {vehicle.short}</Txt></View><GreenLine run={status === 'confirmed'} /><View style={{flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', marginTop: 16}}>{driverRow()}</View><View style={{flexDirection: 'row', justifyContent: 'space-between', marginTop: 12}}><Txt size={12} c="muted">{payment.name}</Txt><Txt size={17} w="700">${ride.price.toFixed(2)}</Txt></View><View style={{flexDirection: 'row', gap: 10, marginTop: 12}}><Btn label="Call" icon="call-outline" variant="soft" height={50} onPress={() => acc && Linking.openURL(`tel:${acc.phone}`)} style={{flex: 1}} /><Btn label="Message" icon="chatbubble-outline" variant="soft" height={50} style={{flex: 1}} /><Btn label="Cancel" icon="close-circle-outline" variant="danger" height={50} onPress={() => { ride.cancel(); onExit(); }} style={{flex: 1}} /></View></Sheet><Sheet visible={live}><View style={{flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center'}}><View style={{flex: 1}}><View style={{flexDirection: 'row', alignItems: 'center', gap: 8}}><Animated.View key={status} entering={FadeIn.duration(250)}><Txt size={22} w="700">{status === 'arrived' ? 'Your driver is here!' : 'Arriving soon'}</Txt></Animated.View>{status === 'arrived' && <Animated.View entering={ZoomIn.duration(300)}><Ionicons name="checkmark-circle" size={24} color={t.green} /></Animated.View>}</View><Txt size={12} c="muted">{status === 'arrived' ? `${first} is waiting at the pickup point` : `${first} is heading to you`}</Txt></View></View><GreenLine run={live} /></Sheet></View>; }
type Step = 'home' | 'route' | 'payment' | 'car' | 'ride'; const ORDER: Step[] = ['home', 'route', 'payment', 'car', 'ride'];
export function WoulibFlow({onClose}: {onClose?: () => void}) { const [step, setStep] = useState<Step>('home'); const [back, setBack] = useState(false); const go = (s: Step) => { setBack(ORDER.indexOf(s) < ORDER.indexOf(step)); setStep(s); }; const enter = back ? SlideInLeft.duration(380) : SlideInRight.duration(380); const exit = back ? SlideOutRight.duration(380) : SlideOutLeft.duration(380); return <WoulibThemeProvider><RideProvider><View style={{flex: 1, overflow: 'hidden'}}><Animated.View key={step} entering={enter} exiting={exit} style={{flex: 1}}>{step === 'home' && <WoulibHomeScreen onFindRide={() => go('route')} onTab={t => t === 'profile' && onClose?.()} />}{step === 'route' && <WoulibRouteScreen onBack={() => go('home')} onContinue={() => go('payment')} />}{step === 'payment' && <WoulibPaymentScreen onBack={() => go('route')} onContinue={() => go('car')} />}{step === 'car' && <WoulibCarScreen onBack={() => go('payment')} onChangePayment={() => go('payment')} onFindDriver={() => go('ride')} />}{step === 'ride' && <WoulibRideScreen onExit={() => go('car')} />}</Animated.View></View></RideProvider></WoulibThemeProvider>; }
